    private static class RecordingLmdbValue implements LmdbValue {

        private static final long serialVersionUID = 1L;

        private final String name;

        private final long id;

        private final ValueStoreRevision revision;

        private final List<String> materialized;

        private boolean initialized;

        private int initCount;

        private int copyCount;

        private LmdbValue copiedFrom;

        private RecordingLmdbValue(String name, long id, ValueStoreRevision revision, List<String> materialized) {
            this.name = name;
            this.id = id;
            this.revision = revision;
            this.materialized = materialized;
        }

        @Override
        public void setInternalID(long id, ValueStoreRevision revision) {
            throw new UnsupportedOperationException();
        }

        @Override
        public long getInternalID() {
            return id;
        }

        @Override
        public void init() {
            initCount++;
            initialized = true;
            materialized.add(name);
        }

        @Override
        public boolean isInitialized() {
            return initialized;
        }

        @Override
        public ValueStoreRevision getValueStoreRevision() {
            return revision;
        }

        @Override
        public void setFromInitializedValue(LmdbValue initializedValue) {
            copyCount++;
            copiedFrom = initializedValue;
        }

        @Override
        public String stringValue() {
            return name;
        }

        @Override
        public String toString() {
            return name;
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) {
                return true;
            }
            if (!(o instanceof RecordingLmdbValue that)) {
                return false;
            }
            return id == that.id && Objects.equals(name, that.name);
        }

        @Override
        public int hashCode() {
            return Objects.hash(name, id);
        }

        public String getNamespace() {
            return "urn:materialized:";
        }

        public String getLocalName() {
            return name;
        }

        @Override
        public long retainedLexicalLength() {
            return name.length();
        }
    }

    @ParameterizedTest
    @ValueSource(booleans = { false, true })
    void connectionInitializesForeignDictionaryValuesBeforeReturningRows(boolean nativeEnabled, @TempDir File dataDir) {
        List<String> materialized = new ArrayList<>();
        ValueStoreRevision revision = new InitializingRevision();
        List<RecordingLmdbValue> foreign = List.of(value("first", 40, revision, materialized), value("second", 30, revision, materialized), value("third", 20, revision, materialized));
        BindingSetAssignment assignment = new BindingSetAssignment();
        assignment.setBindingSets(foreign.stream().<BindingSet>map(LmdbStoreConnectionValueMaterializationTest::row).toList());
        LmdbStoreConfig config = new LmdbStoreConfig().setNativeEvaluationEnabled(nativeEnabled);
        config.setExperimentalQueryOptimizations(true);
        LmdbStore store = new LmdbStore(dataDir, config);
        List<BindingSet> returned = new ArrayList<>();
        store.init();
        try (SailConnection connection = store.getConnection()) {
            connection.begin();
            try (var rows = connection.evaluate(assignment, null, EmptyBindingSet.getInstance(), false)) {
                while (rows.hasNext()) {
                    returned.add(rows.next());
                }
            }
            connection.rollback();
        } finally {
            store.shutDown();
        }
        assertEquals(List.of("first", "second", "third"), materialized);
        assertEquals(3, returned.size());
        for (int i = 0; i < returned.size(); i++) {
            assertEquals("urn:materialized:" + List.of("first", "second", "third").get(i), returned.get(i).getValue("value").stringValue());
        }
    }

    @Test
    void closeDoesNotClearABatchWhileAnotherThreadMaterializesIt() throws Exception {
        List<String> materialized = new ArrayList<>();
        ValueStoreRevision revision = new InitializingRevision();
        CountDownLatch collectionStarted = new CountDownLatch(1);
        CountDownLatch releaseCollection = new CountDownLatch(1);
        CountDownLatch sourceClosed = new CountDownLatch(1);
        BindingSet firstRow = row(value("first", 40, revision, materialized));
        BindingSet secondRow = row(new BlockingLmdbValue("second", 30, revision, materialized, collectionStarted, releaseCollection));
        BindingSet thirdRow = row(value("third", 20, revision, materialized));
        try (LmdbValueMaterializingIteration iteration = new LmdbValueMaterializingIteration(new ListIteration(List.of(firstRow, secondRow, thirdRow), sourceClosed), 8)) {
            assertSame(firstRow, iteration.next());
            CompletableFuture<BindingSet> consuming = CompletableFuture.supplyAsync(iteration::next);
            assertTrue(collectionStarted.await(30, TimeUnit.SECONDS));
            CompletableFuture<Void> closing = CompletableFuture.runAsync(iteration::close);
            assertTrue(sourceClosed.await(30, TimeUnit.SECONDS));
            releaseCollection.countDown();
            assertSame(secondRow, consuming.get(30, TimeUnit.SECONDS));
            closing.get(30, TimeUnit.SECONDS);
            assertFalse(iteration.hasNext());
        } finally {
            releaseCollection.countDown();
        }
    }

    private static void assertBufferedMaterializationOrder() {
        List<String> materialized = new ArrayList<>();
        ValueStoreRevision revision = new InitializingRevision();
        RecordingLmdbValue first = value("first", 40, revision, materialized);
        RecordingLmdbValue id30 = value("id30", 30, revision, materialized);
        RecordingLmdbValue id10 = value("id10", 10, revision, materialized);
        RecordingLmdbValue id20 = value("id20", 20, revision, materialized);
        BindingSet firstRow = row(first);
        BindingSet secondRow = row(id30);
        BindingSet thirdRow = row(id10);
        BindingSet fourthRow = row(id20);
        BindingSetAssignment assignment = new BindingSetAssignment();
        assignment.setBindingSets(List.of(firstRow, secondRow, thirdRow, fourthRow));
        List<BindingSet> assignmentRows = new ArrayList<>();
        assignment.getBindingSets().forEach(assignmentRows::add);
        try (LmdbValueMaterializingIteration result = new LmdbValueMaterializingIteration(new ListIteration(assignmentRows, new CountDownLatch(1)), 8)) {
            assertEquivalentPreparedRow(assignmentRows.get(0), result.next());
            assertEquals(List.of("first"), materialized);
            assertEquivalentPreparedRow(assignmentRows.get(1), result.next());
            assertEquals(List.of("first", "id10", "id20", "id30"), materialized);
            assertEquivalentPreparedRow(assignmentRows.get(2), result.next());
            assertEquivalentPreparedRow(assignmentRows.get(3), result.next());
            assertFalse(result.hasNext());
        }
    }

    private static void assertEquivalentPreparedRow(BindingSet expected, BindingSet actual) {
        assertEquals(expected, actual);
        assertSame(expected.getValue("value"), actual.getValue("value"));
    }

    private static QueryBindingSet row(LmdbValue value) {
        QueryBindingSet row = new QueryBindingSet();
        row.addBinding("value", value);
        return row;
    }

